#include<bits/stdc++.h>
using namespace std;
int main(){const int T=15360,F=512,N=15872;vector<array<int8_t,16>> old(3840),V(T);ifstream a("research/mixed_tier17_eval_subgroup_20261105/cache/mixed17_eval4_orbits.bin",ios::binary);a.read((char*)old.data(),3840*16);vector<uint16_t> H(16),orig(128),K;ifstream b("research/mixed_tier17_eval_subgroup_20261105/cache/mixed17_eval4_group.bin",ios::binary);b.read((char*)H.data(),32);ifstream f("research/mixed_tier17_eval_subgroup_20261105/cache/mixed17_eval4_flat_reps.bin",ios::binary);f.read((char*)orig.data(),256);if(!a||!b||!f)return 2;uint16_t reps[4]={};for(auto h:H){if((h&6)==0)K.push_back(h);else if((h&6)==2&&!reps[1])reps[1]=h;else if((h&6)==4&&!reps[2])reps[2]=h;}reps[3]=reps[1]^reps[2];if(K.size()!=4||!reps[1]||!reps[2])return 3;for(int i=0;i<3840;i++)for(int q=0;q<4;q++)for(int j=0;j<16;j++)V[4*i+q][j]=old[i][j]*((reps[q]>>j&1)?-1:1);vector<uint16_t> flat(F);for(int i=0;i<128;i++)for(int q=0;q<4;q++)flat[4*i+q]=orig[i]^reps[q];ofstream out("research/mixed_tier17_order4_20261105/cache/cross_edges.bin",ios::binary);long long count=0;auto add=[&](int i,int j){out.write((char*)&i,4);out.write((char*)&j,4);count++;};for(int i=0;i<F;i++)add(i,i);for(int i=0;i<T;i++)for(int j=0;j<F;j++){bool bad=false;for(auto h:K){int d=0,w=flat[j]^h;for(int k=0;k<16;k++)d+=V[i][k]*((w>>k&1)?-1:1);if(d>16){bad=true;break;}}if(bad){add(F+i,j);add(j,F+i);}}cout<<"cross edges "<<count<<endl;}
